type MediaReadiness = 'poster' | 'loading' | 'ready' | 'buffering' | 'error';
type PlaybackPhase = 'idle' | 'starting' | 'playing' | 'paused' | 'blocked' | 'error';

interface MediaRendition {
  url: string;
  mimeType: string;
  width: number;
  height: number;
  bitrateKbps: number;
}

interface VideoItem {
  id: string;
  posterUrl: string;
  posterAspectRatio: number;
  durationMs: number;
  renditions: MediaRendition[];
  captionsUrl?: string;
}

interface FeedPage {
  items: VideoItem[];
  nextCursor: string | null;
}

interface MediaSession {
  itemId: string;
  selectedRenditionUrl: string | null;
  readiness: MediaReadiness;
  bufferedSeconds: number;
  errorCode: string | null;
}

interface ActivePlayback {
  itemId: string | null;
  attemptId: string | null;
  phase: PlaybackPhase;
  muted: boolean;
}

interface ViewportIntent {
  candidateId: string | null;
  settledId: string | null;
  direction: 'forward' | 'backward' | 'none';
}
